import java.time.LocalDate;
import java.time.LocalDateTime;

public class SpanBreakdownTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object period(LocalDate from, LocalDate to) {
        try {
            return SpanBreakdown.periodLabel(from, to);
        } catch (Throwable crash) {
            return "periodLabel threw " + crash.getClass().getSimpleName();
        }
    }

    static Object days(LocalDate from, LocalDate to) {
        try {
            return SpanBreakdown.totalDays(from, to);
        } catch (Throwable crash) {
            return "totalDays threw " + crash.getClass().getSimpleName();
        }
    }

    static Object duration(LocalDateTime from, LocalDateTime to) {
        try {
            return SpanBreakdown.durationLabel(from, to);
        } catch (Throwable crash) {
            return "durationLabel threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        LocalDate janEnd = LocalDate.of(2024, 1, 31);
        LocalDate march = LocalDate.of(2024, 3, 5);

        check("periodLabel over a month end", "0y 1m 5d", period(janEnd, march));
        check("totalDays over the same span", 34L, days(janEnd, march));
        check("periodLabel over many years", "23y 11m 30d",
                period(LocalDate.of(2000, 2, 29), LocalDate.of(2024, 2, 28)));
        check("periodLabel backwards is negative", "0y -1m -5d", period(march, janEnd));
        check("totalDays backwards is negative", -34L, days(march, janEnd));
        check("durationLabel across midnight", "26h 30m",
                duration(LocalDateTime.of(2024, 5, 6, 8, 15), LocalDateTime.of(2024, 5, 7, 10, 45)));
        check("durationLabel under an hour", "0h 45m",
                duration(LocalDateTime.of(2024, 5, 6, 23, 30), LocalDateTime.of(2024, 5, 7, 0, 15)));
        check("durationLabel of no time at all", "0h 0m",
                duration(LocalDateTime.of(2024, 5, 6, 8, 15), LocalDateTime.of(2024, 5, 6, 8, 15)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

