/**
 * TASK: Show the difference between a Period (calendar units) and a Duration
 * (exact elapsed time).
 *
 * periodLabel(from, to) uses Period.between and returns "<y>y <m>m <d>d",
 *   e.g. 2024-01-31 to 2024-03-05 -> "0y 1m 5d"
 *   (Period walks the calendar: one month from Jan 31 lands on Feb 29 in 2024,
 *    and there are 5 more days from there.)
 *
 * totalDays(from, to) returns the plain day count with ChronoUnit.DAYS,
 *   e.g. 2024-01-31 to 2024-03-05 -> 34
 *
 * durationLabel(from, to) takes two LocalDateTimes and returns "<h>h <m>m" from
 * a Duration: the hours are the TOTAL hours (toHours), the minutes are only the
 * leftover minutes (toMinutesPart),
 *   e.g. 2024-05-06T08:15 to 2024-05-07T10:45 -> "26h 30m"
 *
 * Going backwards is allowed and produces negative numbers, e.g.
 *   periodLabel(2024-03-05, 2024-01-31) -> "0y -1m -5d"
 */
import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.Period;
import java.time.temporal.ChronoUnit;

public class SpanBreakdown {

    public static String periodLabel(LocalDate from, LocalDate to) {
        Period span = Period.between(from, to);
        return span.getYears() + "y " + span.getMonths() + "m " + span.getDays() + "d";
    }

    public static long totalDays(LocalDate from, LocalDate to) {
        return ChronoUnit.DAYS.between(from, to);
    }

    public static String durationLabel(LocalDateTime from, LocalDateTime to) {
        Duration span = Duration.between(from, to);
        return span.toHours() + "h " + span.toMinutesPart() + "m";
    }
}
